import{z as n,x as B,o as r,c as p,q as s,j as i,D as t,d as o,s as T,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"TTL 与 traceroute","description":"","frontmatter":{"title":"TTL 与 traceroute","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ttl-traceroute.md","filePath":"cs/ttl-traceroute.md","lastUpdated":1791413859000}'),d={name:"cs/ttl-traceroute.md"};function c(u,a,C,P,A,m){const l=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="ttl-与-traceroute" tabindex="-1">TTL 与 traceroute <a class="header-anchor" href="#ttl-与-traceroute" aria-label="Permalink to &quot;TTL 与 traceroute&quot;">​</a></h1><div class="epigraph"><p>TTL/Hop Limit 每跳减一，到零则丢并 ICMP；traceroute 故意让它在沿途逐跳过期，画出一条（可能不对称的）路径快照。</p><footer>—— 据 RFC 791 TTL；RFC 4443 ICMPv6；Van Jacobson traceroute 传统整理</footer></div><p>主干<a href="/cs/icmp">ICMP</a> 已有不可达类型。<a href="/cs/pmtud">上一课</a> 用 ICMP 传 MTU。缺口是<strong>用过期当探针</strong>：traceroute 的 TTL=1,2,… 与 ECMP 下的多路径假象。本课结束域内与域间课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环路时 TTL 防止包永生，接住距离向量病的数据面版本。traceroute：UDP/ICMP/TCP 探针，听 Time Exceeded。ECMP：每次探针哈希不同，画出的「路径」是多条边的拼接，不是一次流的路。MPLS：可能看到 ICMP 来自中间，标签栈影响返回。防火墙丢探针或限速，图残缺。</p><p>不要把 traceroute 当控制面：它看不见 BGP 政策意图，只看见当时数据面。</p><p><span class="marginnote">Paris traceroute 用稳定五元组对付 ECMP。本课钉对象。反向路径不对称常见。</span></p><h3 id="图是快照" tabindex="-1">图是快照 <a class="header-anchor" href="#图是快照" aria-label="Permalink to &quot;图是快照&quot;">​</a></h3><p>TTL 防环并支撑探针。ECMP 会把多条边拼成假路径。过滤 ICMP 与 PMTUD 黑洞同源。看不见 BGP 意图。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：TTL 1 到第一跳，2 到第二跳。对照 ping：ping 固定 TTL 测可达与 RTT，不画图。卫星第一跳 RTT 就很大，图仍短。</p>',11)),(r(),i(E,null,{default:t(()=>[T(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22TTL%3D1%22%5D%20--%3E%20H1%5B%22%E7%AC%AC%E4%B8%80%E8%B7%B3%20ICMP%22%5D%0A%20%20T2%5B%22TTL%3D2%22%5D%20--%3E%20H2%5B%22%E7%AC%AC%E4%BA%8C%E8%B7%B3%22%5D%0A%20%20HASH%5B%22%E6%8E%A2%E9%92%88%E5%93%88%E5%B8%8C%E5%8F%98%22%5D%20--%3E%20FAKE%5B%22ECMP%20%E6%8B%BC%E5%9B%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"与 LLDP 对照：LLDP 一跳身份，traceroute 多跳 IP。与 BGP 收敛对照：路径在收敛中途会跳。RPKI 无效丢弃发生在边界，探针可能突然消失。VXLAN 外层 TTL 与内层独立，排障要看你 ping 的是哪一层。",-1)),a[5]||(a[5]=e("p",null,"安全：TTL 过期消息可泄露拓扑，有人过滤——于是与 PMTUD 黑洞同源。",-1)),a[6]||(a[6]=e("p",null,"一个包在单台路由器内部经历的 TTL 处理：",-1)),(r(),i(E,null,{default:t(()=>[T(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%8C%85%E5%88%B0%E8%BE%BE%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%20--%3E%20DEC%5B%22TTL%20%E5%87%8F%E4%B8%80%22%5D%0A%20%20DEC%20--%3E%20Q%7B%22TTL%20%E4%BB%8D%E4%B8%BA%E6%AD%A3%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20FWD%5B%22%E6%9F%A5%E8%BD%AC%E5%8F%91%E8%A1%A8%E7%BB%A7%E7%BB%AD%E8%BD%AC%E5%8F%91%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E5%B9%B6%E5%9B%9E%E9%80%81%20ICMP%20Time%20Exceeded%22%5D%0A%20%20DROP%20--%3E%20SRC%5B%22%E6%BA%90%E7%AB%99%E6%94%B6%E5%88%B0%2C%20%E8%AE%B0%E4%B8%8B%E8%BF%99%E4%B8%80%E8%B7%B3%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：一条约 15 跳的路径，TTL=1 的探针在第一跳就过期，回来的 ICMP 带 RTT 约 1 ms；TTL=15 才抵达终点。所以 traceroute 对 TTL=1,2,3,… 各发 3 个探针、等 Time Exceeded 回来，就逐跳拼出全路径。</span></p><p><span class="marginnote">常见误区：以为画出的折线是<strong>一个包</strong>走过的路。ECMP 下每个探针按五元组哈希分流，不同 TTL 的探针可能走不同等价路径；Paris traceroute 固定五元组让它们始终同流，图才稳定可读。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 in-band OAM 的全部。路由器架构是下一课序第一课。后课默认：TTL 防环并支撑 traceroute；图是快照且受 ECMP 污染。</p><p>把 traceroute 当 SLA 监测不够：要固定流标识与数据面遥测。</p><p><span class="marginnote">直觉类比：TTL 像牛奶盒上的保质期——每过一个分销商（路由器）剪掉一天，归零就地销毁并回寄一张「我在这里过期了」的通知单。traceroute 就是故意只给一天保质期，沿途逐站收通知单。</span></p><p>下一课<a href="/cs/router-architecture">路由器架构</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TTL 递减防环；零则 ICMP。</li><li>traceroute 是逐跳过期探测。</li><li>ECMP 与过滤使拓扑图不可直读。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 791；RFC 4443；Paris traceroute。</li></ul>',9))])}const h=n(d,[["render",c]]);export{L as __pageData,h as default};
